/** Build a v2 element entity: org-owned, compose-body payload. Exposes `.ref(refName)` and `.def(refName)`. */
export declare function element<F extends Record<string, AppField>, R extends Record<string, FieldRef> = Record<never, never>>(opts: ElementV2Options<F, R>): ElementConfigured<F, R>;
